 36 impl DependencyResolver for ManifestWalkResolver {
 37     fn packages(&self) -> impl Iterator<Item = &Package> {
 38         self.packages.values()
 39     }
 40 
 41     fn dependencies_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
 42         // Avoid an intermediate Vec by streaming index lookups directly as edge references.
 43         let edges = &self.edges;
 44         self.out_index
 45             .get(id)
 46             .into_iter()
 47             .flat_map(|v| v.iter())
 48             .map(move |&idx| &edges[idx])
 49     }
 50 
 51     fn dependents_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
 52         let edges = &self.edges;
 53         self.in_index
 54             .get(id)
 55             .into_iter()
 56             .flat_map(|v| v.iter())
 57             .map(move |&idx| &edges[idx])
 58     }
 59 
 60     fn diagnostics(&self) -> &[Diagnostic] {
 61         &self.diagnostics
 62     }
 63 }
