217 //! Whole-second durations written as `90s`, `6m` or `1h`.
218 
219 use std::time::Duration;
220 
221 /// The longest duration a config value may name.
222 pub const MAX_DURATION: Duration = Duration::from_secs(3600);
223 
224 /// Parses `<digits><s|m|h>`; zero and anything over [`MAX_DURATION`] are rejected.
225 pub fn parse_duration(text: &str) -> Option<Duration> {
226     let (digits, unit) = text.split_at_checked(text.len().checked_sub(1)?)?;
227     let seconds_per_unit = match unit {
228         "s" => 1,
229         "m" => 60,
230         "h" => 3600,
231         _ => return None,
232     };
233     if digits.is_empty() || !digits.bytes().all(|byte| byte.is_ascii_digit()) {
234         return None;
235     }
236     let duration = Duration::from_secs(digits.parse::<u64>().ok()?.checked_mul(seconds_per_unit)?);
237     (!duration.is_zero() && duration <= MAX_DURATION).then_some(duration)
238 }
239 
240 /// The shortest exact spelling: `6m` for 360 seconds, `90s` for 90.
241 pub fn render_duration(duration: Duration) -> String {
242     let seconds = duration.as_secs();
243     if seconds != 0 && seconds.is_multiple_of(3600) {
244         format!("{}h", seconds / 3600)
245     } else if seconds != 0 && seconds.is_multiple_of(60) {
246         format!("{}m", seconds / 60)
247     } else {
248         format!("{seconds}s")
249     }
250 }
251 
252 #[cfg(test)]
253 mod tests {
254     use super::*;
255 
256     #[test]
257     fn each_unit_parses_to_whole_seconds() {
258         assert_eq!(parse_duration("90s"), Some(Duration::from_secs(90)));
259         assert_eq!(parse_duration("6m"), Some(Duration::from_secs(360)));
260         assert_eq!(parse_duration("1h"), Some(Duration::from_secs(3600)));
261     }
262 
263     #[test]
264     fn zero_oversize_and_malformed_values_are_rejected() {
265         for bad in [
266             "",
267             "0s",
268             "61m",
269             "2h",
270             "6",
271             "m",
272             "-5m",
273             "1.5m",
274             " 6m",
275             "6 m",
276             "6M",
277             "99999999999999999999s",
278             "5é",
279             "é",
280         ] {
281             assert_eq!(parse_duration(bad), None, "{bad:?}");
282         }
283     }
284 
285     #[test]
286     fn rendering_round_trips_through_parsing() {
287         for seconds in [1, 59, 60, 90, 120, 360, 3600] {
288             let duration = Duration::from_secs(seconds);
289             assert_eq!(parse_duration(&render_duration(duration)), Some(duration));
290         }
291         assert_eq!(render_duration(Duration::from_secs(360)), "6m");
292         assert_eq!(render_duration(Duration::from_secs(90)), "90s");
293     }
294 }
