316 #[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
317 #[non_exhaustive]
318 pub enum LocateError {
319     #[error("workspace root not found between `{}` and the Git repository root `{}`", .start.display(), .toplevel.display())]
320     #[diagnostic(
321         code(E030),
322         help(
323             "Callisto never searches above the Git repository root. Run `callisto init` there, or add a \
324              callisto.toml, a workspace manifest (Cargo.toml with [workspace], package.json with a workspaces \
325              field, pnpm-workspace.yaml, or a .moon directory) or a package manifest (Cargo.toml with [package], \
326              package.json, or pyproject.toml) inside the repository."
327         )
328     )]
329     WorkspaceRootNotFound { start: PathBuf, toplevel: PathBuf },
330 
331     #[error("`{}` is not inside a Git repository", .start.display())]
332     #[diagnostic(
333         code(E058),
334         help("Callisto needs a Git repository: run `git init` in the workspace root.")
335     )]
336     NotAGitRepository { start: PathBuf },
337 
338     #[error("failed to walk filesystem under `{path}`: {message}")]
339     #[diagnostic(code(E031))]
340     Walk { path: PathBuf, message: String },
341 
342     #[error("project path `{path}` is outside the workspace root `{root}`")]
343     #[diagnostic(code(E032))]
344     OutsideWorkspaceRoot { path: PathBuf, root: PathBuf },
345 
346     #[error("failed to parse manifest `{}`: {message}", .path.display())]
347     #[diagnostic(
348         code(E209),
349         help("Fix the manifest's syntax; a workspace member's manifest is never skipped.")
350     )]
351     ManifestParseError { path: PathBuf, message: String },
352 
353     #[error("failed to read manifest `{}`: {message}", .path.display())]
354     #[diagnostic(
355         code(E310),
356         help("Make the manifest readable UTF-8 text; a workspace member's manifest is never skipped.")
357     )]
358     ManifestReadError { path: PathBuf, message: String },
359 
360     #[error("invalid workspace membership in `{}`: {message}", .path.display())]
361     #[diagnostic(
362         code(E311),
363         help(
364             "Make `members`/`exclude` (Cargo, uv) or `workspaces`/`packages` (npm, pnpm) an array of valid glob strings; \
365              Callisto will not guess which packages a malformed workspace admits."
366         )
367     )]
368     InvalidMembership { path: PathBuf, message: String },
369 
370     #[error("package `{}` is reached through a symbolic link, which Git cannot stage", .path.display())]
371     #[diagnostic(
372         code(E312),
373         help(
374             "Replace the link with the real directory, or list it in a .gitignore under the workspace root so \
375              discovery skips it; Callisto cannot commit a version bump to a file beneath a symbolic link."
376         )
377     )]
378     SymlinkedPackage { path: PathBuf },
379 
380     /// A VCS operation failed during workspace location. This variant exists
381     /// so that callers who need to distinguish filesystem-structure errors
382     /// (WorkspaceRootNotFound, Walk) from VCS errors (e.g., a git repository
383     /// that could not be opened or queried during locate) can do so.
384     #[error("VCS error during workspace location: {0}")]
385     #[diagnostic(code(E033))]
386     Vcs(Box<callisto_model::vcs::VcsError>),
387 
388     #[error(transparent)]
389     #[diagnostic(transparent)]
390     Graph(#[from] Box<crate::error::GraphError>),
391 }
