452 #[derive(Clone, Debug, Default)]
453 pub struct MatrixOptions {
454     /// When Some, restrict the report to exactly this one registered package.
455     /// Must be an ecosystem-qualified id (`cargo/foo`, `npm/foo`); a bare name is rejected with E317.
456     /// Err(GraphError::UnknownPackage) when no registered package matches. Resolved through
457     /// [`crate::IdentityIndex::resolve`], the one selector resolver shared with every other package-selecting surface.
458     pub package: Option<String>,
459     /// Resolve each napi package's addon crate into `manifestPath` (E204 when not exactly one).
460     pub napi_crates: bool,
461 }
462 
463 pub fn matrix<R: CommandRunner, D: DependencyResolver>(
464     ws: &Workspace<'_, R, D>,
465     opts: &MatrixOptions,
466 ) -> Result<MatrixReport, GraphError> {
467     let all_packages: Vec<&callisto_model::Package> = ws.graph.packages().collect();
468 
469     let selected = opts
470         .package
471         .as_deref()
472         .map(|raw| resolve_selected_package(&all_packages, &ws.identity, raw))
473         .transpose()?;
474 
475     let inputs: Vec<MatrixPackageInput> = all_packages
476         .iter()
477         .filter(|p| selected.as_ref().is_none_or(|id| p.id == *id))
478         .map(|p| {
479             let dir_rel = package_dir_rel(p);
480             MatrixPackageInput {
481                 id: p.canonical_id(),
482                 dir_abs: ws.root.join(&dir_rel),
483                 dir_rel,
484                 name: p.id.name().to_string(),
485             }
486         })
487         .collect();
488 
489     let napi_crates = opts
490         .napi_crates
491         .then(|| workspace_napi_crates(ws, &all_packages))
492         .transpose()?;
493     let mut report = build_matrix_report(&inputs, napi_crates.as_deref())?;
494     let mut artifacts = Vec::new();
495     for artifact in ws
496         .config
497         .product_release
498         .iter()
499         .flat_map(|release| &release.artifacts)
500         .filter(|artifact| artifact.package.ecosystem() == Some(callisto_model::Ecosystem::Cargo))
501         .filter(|artifact| {
502             selected
503                 .as_ref()
504                 .is_none_or(|id| ws.identity.identifies(&artifact.package, id))
505         })
506     {
507         let resolved = all_packages.iter().find_map(|package| {
508             let manifest = package
509                 .canonical_manifests()
510                 .find(|manifest| manifest.ecosystem() == callisto_model::Ecosystem::Cargo)?;
511             ws.identity
512                 .identifies(&artifact.package, &package.id)
513                 .then_some((package, manifest))
514         });
515         let Some((package, manifest)) = resolved else {
516             report.diagnostics.push(Diagnostic {
517                 code: DiagnosticCode::UnknownPackage,
518                 severity: DiagnosticSeverity::Warning,
519                 message: format!(
520                     "`[[release.artifact]]` package `{}` (asset `{}`) is not a cargo package in this workspace; it has no matrix entry",
521                     artifact.package, artifact.asset_name
522                 ),
523                 package: Some(artifact.package.clone()),
524                 path: None,
525                 escalated_by: None,
526                 governed_by: None,
527             });
528             continue;
529         };
530         artifacts.push(ReleaseArtifactInput {
531             id: package.canonical_id(),
532             name: package.id.name().to_string(),
533             dir_rel: manifest
534                 .path
535                 .parent()
536                 .map(|dir| dir.to_string_lossy().to_string())
537                 .unwrap_or_default(),
538             target: artifact.target.clone(),
539             asset_name: artifact.asset_name.clone(),
540         });
541     }
542     add_release_artifact_groups(&mut report, &artifacts)?;
543     Ok(report)
544 }
