546 /// Resolves a human-typed `--package` argument (bare or ecosystem-qualified)
547 /// through the one selector resolver, [`crate::IdentityIndex::resolve`] --
548 /// a bare name is accepted only when it names exactly one package.
549 fn resolve_selected_package(
550     all_packages: &[&callisto_model::Package],
551     identity: &crate::IdentityIndex,
552     raw: &str,
553 ) -> Result<PackageId, GraphError> {
554     ConfigError::require_qualified(raw, "--package")?;
555     let resolved = identity.resolve(raw)?;
556     if all_packages.iter().any(|p| p.id == resolved) {
557         Ok(resolved)
558     } else {
559         Err(GraphError::UnknownPackage { id: resolved })
560     }
561 }
562 
563 /// Every workspace cargo package that builds a napi-rs addon.
564 fn workspace_napi_crates<R: CommandRunner, D: DependencyResolver>(
565     ws: &Workspace<'_, R, D>,
566     packages: &[&callisto_model::Package],
567 ) -> Result<Vec<NapiCrate>, GraphError> {
568     let ctx = callisto_manifests::OpenContext::for_workspace_root(&ws.root)?;
569     let mut crates = Vec::new();
570     for decl in packages
571         .iter()
572         .flat_map(|package| package.canonical_manifests())
573         .filter(|decl| decl.format == callisto_model::ManifestFormat::CargoToml)
574     {
575         if let Some(lib_name) = crate::manifest_cache::open_cached(&ws.manifest_cache, decl, &ctx)?.napi_lib_name() {
576             crates.push(NapiCrate {
577                 lib_name,
578                 manifest_path: decl.path.to_string_lossy().into_owned(),
579             });
580         }
581     }
582     Ok(crates)
583 }
