257     fn each_unit_parses_to_whole_seconds() {
258         assert_eq!(parse_duration("90s"), Some(Duration::from_secs(90)));
259         assert_eq!(parse_duration("6m"), Some(Duration::from_secs(360)));
260         assert_eq!(parse_duration("1h"), Some(Duration::from_secs(3600)));
261     }
262 
263     #[test]
264     fn zero_oversize_and_malformed_values_are_rejected() {
265         for bad in [
266             "",
