189 pub struct TagIndex {
190     last: BTreeMap<PackageId, Option<LastTag>>,
191     templates: BTreeMap<PackageId, TagTemplate>,
192     pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
193     /// Tags that match a package's default template by name but were made by another package.
194     foreign: BTreeMap<PackageId, std::collections::BTreeSet<String>>,
195     /// The full, unfiltered raw tag list fetched once during `build` (see
196     /// `fetch_all_tags`), kept around so callers checking whether a specific
197     /// tag name already exists (e.g. the unreleased-version check, once per
198     /// package) can consult this in-memory set instead of re-querying `git`
199     /// once per check.
200     all_tags: std::collections::BTreeSet<String>,
201     /// The commit each tag ends at, read with one `git for-each-ref` the first time a caller asks for any.
202     commits: std::cell::OnceCell<BTreeMap<String, CommitSha>>,
203     pub diagnostics: Vec<Diagnostic>,
204 }
206 impl TagIndex {
207     pub fn build<D: DependencyResolver>(
208         git: &GitAccess<'_>,
209         graph: &D,
210         identity: &IdentityIndex,
211         cfg: &ResolvedConfig,
212     ) -> Result<Self, GraphError> {
213         reject_shared_default_templates(graph)?;
214         let mut last = BTreeMap::new();
215         let mut templates = BTreeMap::new();
216         let mut pre_cursor = BTreeMap::new();
217         let mut foreign: BTreeMap<PackageId, std::collections::BTreeSet<String>> = BTreeMap::new();
218         let mut diagnostics = Vec::new();
220         // Fetch the raw tag list exactly once for the whole build, not once
221         // per package -- see `fetch_all_tags` for why.
222         let all_tag_names = fetch_all_tags(git)?;
223         let all_tags_set: std::collections::BTreeSet<String> = all_tag_names.iter().cloned().collect();
224         let all_tags = SortedTags::new(&all_tag_names);
225         let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();
227         let mut rosters = crate::history::Rosters::default();
228         // The first candidate of every bare-named package is checked below; read their manifests together.
229         let mut wanted = Vec::new();
230         for pkg in graph.packages() {
231             if pkg.tag_template.is_some() || pkg.id.ecosystem().is_some() {
232                 continue;
233             }
234             let (Some(manifest), Ok(grammar)) = (pkg.canonical_manifests().next(), pkg.version_grammar()) else {
235                 continue;
236             };
237             let tmpl = TagTemplate::default_for(&pkg.id);
238             let Ok(candidates) = candidates_cached(&all_tags, &tmpl, &mut glob_cache) else {
239                 continue;
240             };
241             let Ok(selection) = select_last_tag(&tmpl, grammar, candidates.iter().copied()) else {
242                 continue;
243             };
244             if let Some(tag) = take_chosen(selection, &mut Vec::new()) {
245                 wanted.push((tag.name.as_str().to_owned(), manifest.path.clone()));
246             }
247         }
248         rosters.prefetch(git, &wanted);
250         for pkg in graph.packages() {
251             // `TagTemplate::default_for` is the single source of truth for a
252             // package's default tag template -- matches `release.rs`'s own
253             // `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`.
254             // Deliberately not `TagTemplate::parse(&format!("{name}@{{version}}"))`:
255             // `parse` additionally validates git-ref-name legality, which
256             // `default_for` does not, so the two could previously reject/accept a
257             // package name differently. Using `default_for` here removes that
258             // extra validation from this call site to align with the
259             // already-shipped `release.rs` behavior.
260             let tmpl = pkg
261                 .tag_template
262                 .clone()
263                 .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
264             let grammar = pkg.version_grammar()?;
265             let mut chosen = if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
266                 // A bare name is the only evidence the default template has, so a tag is the package's only if its
267                 // commit did not hold the name in another ecosystem.
268                 let mut candidates = candidates_cached(&all_tags, &tmpl, &mut glob_cache)?;
269                 loop {
270                     let selection = select_last_tag(&tmpl, grammar, candidates.iter().copied())?;
271                     let Some(tag) = take_chosen(selection, &mut diagnostics) else {
272                         break None;
273                     };
274                     // History that cannot be read is no evidence of another owner.
275                     let held = crate::history::may_have_held_name_at(
276                         git,
277                         tag.name.as_str(),
278                         pkg.id.name(),
279                         pkg,
280                         identity,
281                         &mut rosters,
282                     )
283                     .unwrap_or(true);
284                     if held {
285                         break Some(tag);
286                     }
287                     diagnostics.push(foreign_tag_diagnostic(&pkg.id, tag.name.as_str()));
288                     foreign
289                         .entry(pkg.id.clone())
290                         .or_default()
291                         .insert(tag.name.as_str().to_string());
292                     candidates.retain(|candidate| *candidate != tag.name.as_str());
293                 }
294             } else {
295                 take_chosen(
296                     select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?,
297                     &mut diagnostics,
298                 )
299             };
300             if chosen.is_none() {
301                 let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
302                 if let Some(previous) = crate::config::resolve::resolve_package_config(&native_names, cfg)
303                     .map(|package_config| package_config.previous_tag_templates.as_slice())
304                 {
305                     for template in previous {
306                         chosen = take_chosen(
307                             select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?,
308                             &mut diagnostics,
309                         );
310                         if chosen.is_some() {
311                             break;
312                         }
313                     }
314                 }
315             }
316             if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
317                 // A promoted package keeps the `{name}@` tags it made while its name was unique.
318                 let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
319                 let same: Vec<&callisto_model::Package> = graph
320                     .packages()
321                     .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
322                     .collect();
323                 let mut owned = Vec::new();
324                 for tag in matching_tags(&all_tags, &unqualified)? {
325                     if crate::history::sole_owner_at(git, tag, pkg.id.name(), &same, identity, &mut rosters)?
326                         .is_some_and(|owner| owner.id == pkg.id)
327                     {
328                         owned.push(tag);
329                     }
330                 }
331                 chosen = take_chosen(
332                     select_last_tag(&unqualified, grammar, owned).map_err(GraphError::from)?,
333                     &mut diagnostics,
334                 );
335             }
336             if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
337                 // A demoted package keeps the qualified tags it made while its name was shared.
338                 if let Some(manifest) = pkg.canonical_manifests().next() {
339                     let qualified = TagTemplate::default_for(&PackageId::Prefixed {
340                         ecosystem: manifest.ecosystem(),
341                         name: pkg.id.name().to_string(),
342                     });
343                     let qualified_last = take_chosen(
344                         select_last_tag(&qualified, grammar, all_tags.0.iter().copied()).map_err(GraphError::from)?,
345                         &mut diagnostics,
346                     );
347                     chosen = newest(chosen, qualified_last);
348                 }
349             }
350             last.insert(pkg.id.clone(), chosen);
351             templates.insert(pkg.id.clone(), tmpl);
352             pre_cursor.insert(pkg.id.clone(), None);
353         }
355         Ok(TagIndex {
356             last,
357             templates,
358             pre_cursor,
359             foreign,
360             all_tags: all_tags_set,
361             commits: std::cell::OnceCell::new(),
362             diagnostics,
363         })
364     }
366     pub fn last_tag(&self, id: &PackageId) -> Option<&LastTag> {
367         self.last.get(id).and_then(|opt| opt.as_ref())
368     }
370     pub fn template(&self, id: &PackageId) -> &TagTemplate {
371         &self.templates[id]
372     }
374     pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
375         self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
376     }
378     /// Returns whether `tag_name` is present in the raw tag list fetched
379     /// during `build` -- an exact match, not a glob. Lets callers checking
380     /// tag existence once per package (e.g. `derive_unreleased_decision`)
381     /// consult this in-memory set instead of shelling out to `git` again
382     /// for each one.
383     pub fn contains_tag(&self, tag_name: &str) -> bool {
384         self.all_tags.contains(tag_name)
385     }
387     /// The commit `tag_name` ends at. Every tag is read in one process the first time, so asking once per package
388     /// costs no process each; a tag that ends at something else is left to `git rev-parse`.
389     pub fn commit_of(&self, git: &GitAccess<'_>, tag_name: &str) -> Result<Option<CommitSha>, GraphError> {
390         if !self.all_tags.contains(tag_name) {
391             return Ok(git.resolve_commit(&format!("refs/tags/{tag_name}"))?);
392         }
393         if self.commits.get().is_none() {
394             let commits = git
395                 .tags_with_commits()?
396                 .into_iter()
397                 .filter_map(|(name, commit)| Some((name.as_str().to_owned(), commit?)))
398                 .collect();
399             drop(self.commits.set(commits));
400         }
401         match self.commits.get().and_then(|commits| commits.get(tag_name)) {
402             Some(commit) => Ok(Some(commit.clone())),
403             None => Ok(git.resolve_commit(&format!("refs/tags/{tag_name}"))?),
404         }
405     }
407     /// Whether `tag_name` exists and was made by `id`, not by another package that held the same name.
408     pub fn is_tag_of(&self, id: &PackageId, tag_name: &str) -> bool {
409         self.contains_tag(tag_name) && !self.foreign.get(id).is_some_and(|tags| tags.contains(tag_name))
410     }
412     /// Constructs an empty `TagIndex` with no packages or tags — useful in
413     /// unit tests that do not exercise tag-based logic.
414     pub fn empty() -> Self {
415         TagIndex {
416             last: BTreeMap::new(),
417             templates: BTreeMap::new(),
418             pre_cursor: BTreeMap::new(),
419             foreign: BTreeMap::new(),
420             all_tags: std::collections::BTreeSet::new(),
421             commits: std::cell::OnceCell::new(),
422             diagnostics: Vec::new(),
423         }
424     }
