 14 /// Fetches the full, unfiltered list of every tag name in the repository.
 15 ///
 16 /// Deliberately fetches with no glob pattern: callers filter afterwards via
 17 /// [`matching_tags`], so the fetch batches once across every package (see
 18 /// [`TagIndex::build`]) instead of one `git` spawn per package.
 19 pub(crate) fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
 20     let tags = git.list_tags(None)?;
 21     Ok(tags.into_iter().map(|t| t.as_str().to_string()).collect())
 22 }
 24 /// Tag names in byte order. The tags beginning with a literal prefix are one contiguous run, found by binary search, so
 25 /// matching a template against them does not test every tag in the repository.
 26 struct SortedTags<'a>(Vec<&'a str>);
 28 impl<'a> SortedTags<'a> {
 29     fn new(tags: &'a [String]) -> Self {
 30         let mut sorted: Vec<&str> = tags.iter().map(String::as_str).collect();
 31         sorted.sort_unstable();
 32         SortedTags(sorted)
 33     }
 35     fn starting_with(&self, prefix: &str) -> &[&'a str] {
 36         let start = self.0.partition_point(|tag| *tag < prefix);
 37         let run = self.0[start..].iter().take_while(|tag| tag.starts_with(prefix)).count();
 38         &self.0[start..start + run]
 39     }
 40 }
 42 /// Filters `all_tags` down to those matching `template`'s glob.
 43 ///
 44 /// Compiles the glob via [`callisto_model::vcs::compile_tag_glob`] -- the same
 45 /// helper `GitAccess::list_tags` uses -- so tag selection is identical
 46 /// either way. Includes error behavior: a
 47 /// `template.glob()` that fails to compile surfaces as
 48 /// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
 49 /// the unsafe alternative, since a malformed template must never silently
 50 /// make "last tag" resolution pick an unrelated package's tag.
 51 fn matching_tags<'a>(all_tags: &SortedTags<'a>, template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
 52     let glob = template.glob();
 53     GLOB_COMPILE_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
 54     let matcher = callisto_model::vcs::compile_tag_glob(&glob).map_err(GraphError::Vcs)?;
 56     // A match must begin with the glob's literal text before its first wildcard, so only that run is tested.
 57     let literal = glob
 58         .split(['*', '?', '[', ']', '{', '}', '\\'])
 59         .next()
 60         .unwrap_or_default();
 61     Ok(all_tags
 62         .starting_with(literal)
 63         .iter()
 64         .copied()
 65         .filter(|tag| matcher.is_match(tag))
 66         .collect())
 67 }
 69 /// Test-observability counter: total number of times [`matching_tags`] has
 70 /// compiled a fresh `globset::Glob`. Production code never reads this; it
 71 /// exists so tests can assert `TagIndex::build` compiles/scans at most once
 72 /// per *distinct* tag-template glob, not once per package -- a
 73 /// `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template` can
 74 /// apply the identical template string to many packages at once.
 75 static GLOB_COMPILE_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
 77 /// Resets the internal glob-compile call counter to zero. Intended for use in test setup.
 78 ///
 79 /// Process-global, like `callisto_manifests::reset_open_call_count` -- exact
 80 /// counts must be asserted from an isolated integration-test binary under
 81 /// `#[serial]`, not an inline unit test sharing this crate's `--lib`
 82 /// process with other, non-serial tests (see
 83 /// `tests/tag_glob_cache_count_test.rs`).
 84 pub fn reset_glob_compile_count() {
 85     GLOB_COMPILE_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
 86 }
 88 /// Reads the current value of the internal glob-compile call counter.
 89 pub fn glob_compile_count() -> usize {
 90     GLOB_COMPILE_COUNT.load(std::sync::atomic::Ordering::SeqCst)
 91 }
 93 /// Selects the highest-versioned tag matching `template` out of a full tag
 94 /// list previously obtained via [`fetch_all_tags`], reusing a `cache` of
 95 /// already-compiled/already-scanned candidates keyed by `template.glob()`
 96 /// -- a `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template`
 97 /// string applies the identical template to every matching package, so
 98 /// without this cache `TagIndex::build`'s per-package loop would recompile
 99 /// the same `globset::Glob` and rescan the full tag list once per package
100 /// sharing that template, instead of once per distinct template.
101 fn select_from_tags_cached<'a>(
102     all_tags: &SortedTags<'a>,
103     template: &TagTemplate,
104     grammar: VersionGrammar,
105     cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
106 ) -> Result<LastTagSelection, GraphError> {
107     let candidates = candidates_cached(all_tags, template, cache)?;
108     select_last_tag(template, grammar, candidates).map_err(GraphError::from)
109 }
111 /// The tags matching `template`, scanned once per distinct glob.
112 fn candidates_cached<'a>(
113     all_tags: &SortedTags<'a>,
114     template: &TagTemplate,
115     cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
116 ) -> Result<Vec<&'a str>, GraphError> {
117     let glob = template.glob();
118     if let Some(cached) = cache.get(&glob) {
119         return Ok(cached.clone());
120     }
121     let matched = matching_tags(all_tags, template)?;
122     cache.insert(glob, matched.clone());
123     Ok(matched)
124 }
126 /// Keeps the chosen tag and records each skipped-tag warning once, however many packages scan the same tags.
127 fn take_chosen(selection: LastTagSelection, diagnostics: &mut Vec<Diagnostic>) -> Option<LastTag> {
128     for diagnostic in selection.skipped {
129         if !diagnostics.iter().any(|seen| seen.message == diagnostic.message) {
130             diagnostics.push(diagnostic);
131         }
132     }
133     selection.chosen
134 }
136 /// The higher-versioned of two tags found for one package; `first` wins a tie.
137 fn newest(first: Option<LastTag>, second: Option<LastTag>) -> Option<LastTag> {
138     match (first, second) {
139         (Some(first), Some(second)) => {
140             let newer = second
141                 .version
142                 .compare(&first.version)
143                 .is_ok_and(std::cmp::Ordering::is_gt);
144             Some(if newer { second } else { first })
145         }
146         (first, second) => first.or(second),
147     }
148 }
150 /// E101 when a package's default template (`{name}@{version}`) is also another package's template.
151 fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
152     let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
153     for pkg in graph.packages() {
154         let tmpl = pkg
155             .tag_template
156             .clone()
157             .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
158         let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
159         *has_default |= pkg.tag_template.is_none();
160         ids.push(pkg.id.clone());
161     }
162     match by_template
163         .into_iter()
164         .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
165     {
166         Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
167         None => Ok(()),
168     }
169 }
171 /// The advisory for a tag a package matched by name but did not make.
