  14 /// The ecosystems with a manifest declaring a name at a revision, for every (revision, name) already read, and the
  15 /// manifest texts read so far.
  16 #[derive(Default)]
  17 pub(crate) struct Rosters {
  18     declaring: HashMap<(String, String), BTreeSet<Ecosystem>>,
  19     texts: HashMap<(String, PathBuf), Option<String>>,
  20 }
  21 
  22 impl Rosters {
  23     /// Reads every `(rev, path)` not read yet in one `git cat-file --batch`, so the lookups that follow cost no process.
  24     ///
  25     /// A failed batch is not an error: the lookups then read one at a time, as they always could.
  26     pub(crate) fn prefetch(&mut self, git: &GitAccess<'_>, wanted: &[(String, PathBuf)]) {
  27         let missing: Vec<&(String, PathBuf)> = wanted.iter().filter(|key| !self.texts.contains_key(*key)).collect();
  28         let objects: Vec<String> = missing
  29             .iter()
  30             .map(|(rev, path)| format!("{rev}:./{}", path.display()))
  31             .collect();
  32         let Ok(blobs) = batch_blobs(git.runner(), git.root(), &objects) else {
  33             return;
  34         };
  35         for (key, blob) in missing.into_iter().zip(blobs) {
  36             let text = match blob {
  37                 BatchBlob::Blob(text) => Some(text),
  38                 BatchBlob::Missing => None,
  39             };
  40             self.texts.insert(key.clone(), text);
  41         }
  42     }
  43 
  44     fn manifest_text(&mut self, git: &GitAccess<'_>, rev: &str, path: &Path) -> Result<Option<String>, GraphError> {
  45         let key = (rev.to_owned(), path.to_path_buf());
  46         if let Some(known) = self.texts.get(&key) {
  47             return Ok(known.clone());
  48         }
  49         let text = git.read_at(rev, path)?;
  50         self.texts.insert(key, text.clone());
  51         Ok(text)
  52     }
  53 
  54     fn declaring_at(&mut self, git: &GitAccess<'_>, rev: &str, name: &str) -> Result<BTreeSet<Ecosystem>, GraphError> {
  55         let key = (rev.to_string(), name.to_string());
  56         if let Some(known) = self.declaring.get(&key) {
  57             return Ok(known.clone());
  58         }
  59         let mut declaring = BTreeSet::new();
  60         for (ecosystem, format, file_name) in MANIFESTS {
  61             if declares(git, rev, name, ecosystem, format, file_name)? {
  62                 declaring.insert(ecosystem);
  63             }
  64         }
  65         self.declaring.insert(key, declaring.clone());
  66         Ok(declaring)
  67     }
  68 }
