  76 /// Whether `rev` held a manifest of `ecosystem` declaring `name`; only manifests mentioning it are read.
  77 fn declares(
  78     git: &GitAccess<'_>,
  79     rev: &str,
  80     name: &str,
  81     ecosystem: Ecosystem,
  82     format: ManifestFormat,
  83     file_name: &str,
  84 ) -> Result<bool, GraphError> {
  85     // A normalized Python name may be spelled with other separators, so search its first word.
  86     let needle = match ecosystem {
  87         Ecosystem::Pypi => name
  88             .split(['-', '_', '.'])
  89             .find(|word| !word.is_empty())
  90             .unwrap_or(name),
  91         _ => name,
  92     };
  93     for path in git.files_containing_at(rev, needle, &[&format!(":(glob)**/{file_name}")])? {
