  95             continue;
  96         };
  97         // A manifest that was broken at `rev` simply names nobody.
  98         let declared = read_identity(format, &text, &path)
  99             .ok()
 100             .and_then(|identity| identity.name);
 101         if declared.is_some_and(|declared| names_equal(ecosystem, &declared, name)) {
 102             return Ok(true);
 103         }
 104     }
 105     Ok(false)
