 108 fn names_equal(ecosystem: Ecosystem, left: &str, right: &str) -> bool {
 109     match ecosystem {
 110         Ecosystem::Pypi => normalize_pypi_project_name(left) == normalize_pypi_project_name(right),
 111         _ => left == right,
 112     }
 113 }
 114 
 115 /// Whether `pkg`'s current first manifest held a manifest declaring `name` at `rev`.
 116 fn first_manifest_declares_at(
 117     git: &GitAccess<'_>,
 118     rev: &str,
 119     pkg: &Package,
 120     name: &str,
 121     rosters: &mut Rosters,
 122 ) -> Result<bool, GraphError> {
 123     let Some(manifest) = pkg.canonical_manifests().next() else {
 124         return Ok(false);
 125     };
 126     let path = Path::new(&manifest.path);
 127     let Some(text) = rosters.manifest_text(git, rev, path)? else {
 128         return Ok(false);
 129     };
 130     // A manifest that was broken at `rev` simply names nobody.
 131     let declared = read_identity(manifest.format, &text, path)
 132         .ok()
 133         .and_then(|identity| identity.name);
 134     Ok(declared.is_some_and(|declared| names_equal(manifest.ecosystem(), &declared, name)))
 135 }
