 137 /// The one package among `candidates` that owned the bare name `name` at `rev`, if exactly one did.
 138 ///
 139 /// A candidate whose current first manifest path held a manifest declaring `name` at `rev` owns it. When none does,
 140 /// the package moved or changed its primary manifest, so ownership is whichever package has a manifest named `name`
 141 /// today in an ecosystem where `rev` also held a manifest named `name`.
 142 pub(crate) fn sole_owner_at<'p>(
 143     git: &GitAccess<'_>,
 144     rev: &str,
 145     name: &str,
 146     candidates: &[&'p Package],
 147     identity: &IdentityIndex,
 148     rosters: &mut Rosters,
 149 ) -> Result<Option<&'p Package>, GraphError> {
 150     let mut owner = None;
 151     for pkg in candidates {
 152         if first_manifest_declares_at(git, rev, pkg, name, rosters)? {
 153             if owner.is_some() {
 154                 return Ok(None);
 155             }
 156             owner = Some(*pkg);
 157         }
 158     }
 159     if owner.is_some() {
 160         return Ok(owner);
 161     }
 162     let declaring = rosters.declaring_at(git, rev, name)?;
 163     let mut holders = candidates.iter().filter(|pkg| {
 164         declaring.iter().any(|ecosystem| {
 165             identity
 166                 .native_name(&pkg.id, *ecosystem)
 167                 .is_some_and(|native| names_equal(*ecosystem, native, name))
 168         })
 169     });
 170     let first = holders.next();
 171     Ok(if holders.next().is_some() { None } else { first.copied() })
 172 }
