   6 impl IdentityIndex {
   7     /// Runs `lookup` on the by-package view of `native` and `platform`, building it first when it is missing or stale.
   8     fn by_package<T>(&self, lookup: impl FnOnce(&ByPackage) -> T) -> T {
   9         let sizes = (self.native.len(), self.platform.len());
  10         let mut cached = self
  11             .by_package
  12             .0
  13             .lock()
  14             .unwrap_or_else(std::sync::PoisonError::into_inner);
  15         if cached.as_ref().is_some_and(|known| known.sizes != sizes) {
  16             *cached = None;
  17         }
  18         let view = cached.get_or_insert_with(|| {
  19             let mut view = ByPackage {
  20                 sizes,
  21                 ..ByPackage::default()
  22             };
  23             for ((ecosystem, name), id) in &self.native {
  24                 view.native
  25                     .entry(id.clone())
  26                     .or_default()
  27                     .push((*ecosystem, name.clone()));
  28             }
  29             for (name, (owner, _, _)) in &self.platform {
  30                 view.platform.entry(owner.clone()).or_default().push(name.clone());
  31             }
  32             view
  33         });
  34         lookup(view)
  35     }
  37     /// The one selector resolver: resolves a user- or config-typed package
  38     /// selector (`eco/name` or a bare name; the colon form is `E316`) against registered
  39     /// native manifest names.
  40     ///
  41     /// A qualified selector is an exact `(ecosystem, native name)` lookup: no
  42     /// match is `E102` ([`GraphError::UnknownPackage`]), regardless of what a
  43     /// different ecosystem calls itself. A bare selector searches every
  44     /// ecosystem's native names: no match is `E102`; more than one distinct
  45     /// package answering to that name in different ecosystems is `E103`
  46     /// ([`GraphError::AmbiguousName`]). Resolving by any registered native
  47     /// name -- not just a package's primary/display name -- is what lets a
  48     /// dual-manifest package be named by either of its manifests' names.
  49     pub fn resolve(&self, selector: &str) -> Result<PackageId, GraphError> {
  50         ConfigError::reject_colon_form(selector, "package selector")?;
  51         let id = PackageId::parse(selector).unwrap_or_else(|_| PackageId::Bare(selector.to_string()));
  52         self.resolve_id(&id)
  53     }
  55     /// [`Self::resolve`] for an already-parsed selector.
  56     pub fn resolve_id(&self, id: &PackageId) -> Result<PackageId, GraphError> {
  57         match id {
  58             PackageId::Prefixed { ecosystem, name } => self
  59                 .native
  60                 .get(&(*ecosystem, name.clone()))
  61                 .cloned()
  62                 .ok_or_else(|| GraphError::UnknownPackage { id: id.clone() }),
  63             PackageId::Bare(name) => {
  64                 let candidates: BTreeSet<PackageId> = self
  65                     .native
  66                     .iter()
  67                     .filter(|((_, n), _)| n == name)
  68                     .map(|(_, registered)| registered.clone())
  69                     .collect();
  70                 match candidates.len() {
  71                     0 => Err(GraphError::UnknownPackage { id: id.clone() }),
  72                     1 => Ok(candidates.into_iter().next().expect("len checked above")),
  73                     _ => Err(GraphError::AmbiguousName {
  74                         name: name.clone(),
  75                         candidates: candidates.into_iter().collect(),
  76                     }),
  77                 }
  78             }
  79         }
  80     }
  82     /// True when `selector` (an ecosystem-qualified or bare configured
  83     /// package identity, e.g. from `[[release.artifact]]` or
