  90     /// selector for one ecosystem's package would otherwise match a
  91     /// same-named package in another.
  92     pub fn identifies(&self, selector: &PackageId, candidate: &PackageId) -> bool {
  93         self.resolve_id(selector).is_ok_and(|resolved| &resolved == candidate)
