  97     ///
  98     /// Python names use PEP 503 equivalence; other ecosystems use exact names.
  99     /// If no name matches within the ecosystem -- a
 100     /// package in one ecosystem depending on a different ecosystem's
 101     /// package by bare name (e.g. an npm package listing a cargo crate)
 102     /// -- falls back to scanning all ecosystems for `name`.
 103     ///
 104     /// Fallback finds exactly one match: returns it. Finds more than one
 105     /// (two ecosystems both have `name`): returns `None` to prevent
 106     /// silent misresolution -- callers holding a `&mut Vec<Diagnostic>`
 107     /// should use [`Self::resolve_native_with_fallback`] instead, to get
 108     /// a diagnostic.
 109     pub fn resolve_native(&self, eco: Ecosystem, name: &str) -> Option<&PackageId> {
 110         match self.native_in_ecosystem(eco, name) {
 111             Ok(Some(id)) => return Some(id),
 112             Ok(None) => {}
 113             Err(_) => return None,
 114         }
