218	/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
219	/// modeled as an enum rather than two independent bools so the type system
220	/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
221	/// false, feat_to_patch: true}`-shaped struct literal could otherwise
222	/// construct.
223	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
224	pub enum PreMajorInferencePolicy {
225	    #[default]
226	    Off,
227	    /// Downgrades an inferred Major bump to Minor.
228	    Conservative,
229	    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.
230	    ConservativeFeat,
231	}
232	
233	pub fn parse_publish_target(s: &str) -> Result<PublishTarget, ConfigError> {
234	    match s {
235	        "crates-io" => Ok(PublishTarget::CratesIo),
236	        "npm" => Ok(PublishTarget::Npm {
237	            registry: None,
238	            access: None,
239	        }),
240	        "pypi" => Ok(PublishTarget::Pypi { index: None }),
241	        "nuget" => Ok(PublishTarget::NuGet { source: None }),
242	        "github-release" => Ok(PublishTarget::GitHubRelease),
243	        "none" => Ok(PublishTarget::None),
244	        other => Err(ConfigError::UnknownKey {
245	            path: PathBuf::new(),
246	            key: format!("publish-to = {other:?}"),
247	        }),
248	    }
249	}
250	
251	pub fn parse_release_trigger(s: &str) -> Result<ReleaseTrigger, ConfigError> {
252	    match s {
253	        "changeset" => Ok(ReleaseTrigger::Changeset),
254	        "auto" => Ok(ReleaseTrigger::Auto),
255	        other => Err(ConfigError::UnknownKey {
256	            path: PathBuf::new(),
257	            key: format!("release-trigger = {other}"),
258	        }),
259	    }
260	}
261	
262	/// A `[[package]]` rule applies to a package when it has a manifest in the rule's ecosystem whose own name is the
263	/// rule's name.
264	///
265	/// `native_names` is the package's name in each ecosystem it has a manifest in. A dual package's names can differ per
266	/// ecosystem, so `npm/michi-node` does not apply to the package whose npm name is `@orin-dx/michi`, whatever its
267	/// directory or Cargo name is, which is the same identity a `[[fixed-group]]` member must give.
268	pub(crate) fn rule_applies(rule_id: &PackageId, native_names: &[(Ecosystem, &str)]) -> bool {
269	    rule_id.ecosystem().is_some_and(|eco| {
270	        native_names
271	            .iter()
272	            .any(|(ecosystem, name)| *ecosystem == eco && *name == rule_id.name())
273	    })
274	}
275	
276	/// The first `[[package]]` rule, in TOML declaration order, that applies to `id`; `None` if none does.
277	///
278	/// MUST NOT sort or partition `cfg.packages`: declaration order is the specificity.
279	pub(crate) fn resolve_package_config<'a>(
280	    native_names: &[(Ecosystem, &str)],
281	    cfg: &'a ResolvedConfig,
282	) -> Option<&'a PackageConfig> {
283	    cfg.packages
284	        .iter()
285	        .find(|(rule_id, _)| rule_applies(rule_id, native_names))
286	        .map(|(_, pcfg)| pcfg)
287	}
288	
289	pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
290	    match s {
291	        "off" | "false" => Ok(PreMajorInferencePolicy::Off),
292	        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
293	        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
294	        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
295	    }
296	}
