298	/// Parses the five override fields shared by `[[package]]` and
299	/// `[[package-set]]` blocks (release-trigger, tag-template, changelog,
300	/// pre-major-inference, publish-to) into a `PackageConfig`.
301	///
302	/// `previous_tag_templates` is `[[package]]`-only; `[[package-set]]` callers pass `None`.
303	#[allow(clippy::too_many_arguments)]
304	fn parse_package_config_fields(
305	    callisto_toml: &Path,
306	    error_prefix: &str,
307	    pattern_display: &str,
308	    release_trigger: Option<&str>,
309	    tag_template: Option<&str>,
310	    previous_tag_templates: Option<&[String]>,
311	    changelog: Option<&str>,
312	    pre_major_inference: Option<&str>,
313	    publish_to: Option<&[String]>,
314	) -> Result<PackageConfig, ConfigError> {
315	    let release_trigger = release_trigger.map(parse_release_trigger).transpose()?;
316	
317	    let tag_template = tag_template
318	        .map(TagTemplate::parse)
319	        .transpose()
320	        .map_err(ConfigError::Tag)?;
321	
322	    let previous_tag_templates = previous_tag_templates
323	        .unwrap_or_default()
324	        .iter()
325	        .map(|template| TagTemplate::parse(template))
326	        .collect::<Result<Vec<_>, _>>()
327	        .map_err(ConfigError::Tag)?;
328	
329	    let changelog = changelog
330	        .map(|s| {
331	            callisto_model::workspace_relative(s).map_err(|_err| ConfigError::InvalidChangelogPath {
332	                pattern: pattern_display.to_string(),
333	                value: s.to_string(),
334	            })
335	        })
336	        .transpose()?;
337	
338	    let pre_major_inference = pre_major_inference.map(parse_pre_major_policy).transpose()?;
339	
340	    let publish_to = publish_to
341	        .map(|targets| {
342	            targets
343	                .iter()
344	                .map(|s| parse_publish_target(s))
345	                .collect::<Result<Vec<_>, _>>()
346	        })
347	        .transpose()
348	        .map_err(|e| match e {
349	            ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
350	                path: callisto_toml.to_path_buf(),
351	                key: format!("{error_prefix} publish-to: {key}"),
352	            },
353	            other => other,
354	        })?;
355	
356	    Ok(PackageConfig {
357	        release_trigger,
358	        publish_to,
359	        tag_template,
360	        previous_tag_templates,
361	        changelog,
362	        pre_major_inference,
363	    })
364	}
