366	/// Reads and parses `root/callisto.toml` (absent means empty), then [`resolve`]s it.
367	pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
368	    let callisto_toml = root.join("callisto.toml");
369	    let content = callisto_model::strict_fs::read_optional(&callisto_toml).map_err(|e| ConfigError::Read {
370	        path: callisto_toml.clone(),
371	        message: e.to_string(),
372	    })?;
373	    let raw = if let Some(content) = content {
374	        toml::from_str::<RawConfig>(&content).map_err(|e| ConfigError::ParseToml {
375	            path: callisto_toml.clone(),
376	            message: e.to_string(),
377	        })?
378	    } else {
379	        RawConfig::default()
380	    };
381	    resolve(root, raw)
382	}
383	
384	/// Validates and defaults an already-parsed config for the workspace at `root`.
385	pub fn resolve(root: &Path, raw: RawConfig) -> Result<ResolvedConfig, ConfigError> {
386	    let callisto_toml = root.join("callisto.toml");
387	    let mut provenance = BTreeMap::new();
388	    let product_release = raw.release.map(resolve_product_release).transpose()?;
389	
390	    let changesets_dir_str = raw
391	        .changesets
392	        .as_ref()
393	        .and_then(|c| c.dir.as_deref())
394	        .unwrap_or(".changeset");
395	
396	    // Reject any changesets.dir value that is absolute or contains '..'
397	    // components — either would allow load_changesets / atomic_write to
398	    // escape the workspace root. We check components() rather than
399	    // canonicalizing because the directory may not exist yet (e.g. a fresh
400	    // workspace).
401	    let changesets_dir =
402	        callisto_model::workspace_relative(changesets_dir_str).map_err(|_err| ConfigError::InvalidChangesetsDir {
403	            dir: changesets_dir_str.to_string(),
404	        })?;
405	
406	    let cascade_raw = raw.cascade.unwrap_or_default();
407	    let mode = match cascade_raw.mode.as_deref() {
408	        Some("always") => {
409	            provenance.insert(ConfigKey::CASCADE_MODE, ConfigProvenance::Explicit);
410	            CascadeMode::Always
411	        }
412	        Some("out-of-range") | None => CascadeMode::OutOfRange,
413	        Some(other) => {
414	            return Err(ConfigError::UnknownKey {
415	                path: callisto_toml,
416	                key: format!("cascade.mode = {other}"),
417	            })
418	        }
419	    };
420	
421	    let bump_severity = match cascade_raw.bump_severity.as_deref() {
422	        Some("minor") => {
423	            provenance.insert(ConfigKey::CASCADE_BUMP_SEVERITY, ConfigProvenance::Explicit);
424	            CascadeBumpSeverity::Minor
425	        }
426	        Some("patch") | None => CascadeBumpSeverity::Patch,
427	        Some(other) => {
428	            return Err(ConfigError::InvalidBumpSeverity {
429	                found: other.to_string(),
430	            })
431	        }
432	    };
433	
434	    let peer_escalation = cascade_raw.peer_escalation.unwrap_or(true);
435	    if cascade_raw.peer_escalation.is_some() {
436	        provenance.insert(ConfigKey::CASCADE_PEER_ESCALATION, ConfigProvenance::Explicit);
437	    }
438	
439	    let preserve_npm_ranges = cascade_raw.preserve_npm_ranges.unwrap_or(true);
440	    if cascade_raw.preserve_npm_ranges.is_some() {
441	        provenance.insert(ConfigKey::CASCADE_PRESERVE_NPM_RANGES, ConfigProvenance::Explicit);
442	    }
443	
444	    let validation_raw = raw.validation.unwrap_or_default();
445	    let allow_empty_changesets = validation_raw.allow_empty_changesets.unwrap_or(false);
446	    if validation_raw.allow_empty_changesets.is_some() {
447	        provenance.insert(ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS, ConfigProvenance::Explicit);
448	    }
449	
450	    let mut registries = BTreeMap::new();
451	    registries.insert(
452	        RegistryKey(RegistryKey::CRATES_IO.to_string()),
453	        RegistryConfig {
454	            kind: Ecosystem::Cargo,
455	            url: None,
456	            publish_url: None,
457	            confirm_timeout: None,
458	            publish_timeout: None,
459	        },
460	    );
461	    registries.insert(
462	        RegistryKey(RegistryKey::NPM.to_string()),
463	        RegistryConfig {
464	            kind: Ecosystem::Npm,
465	            url: None,
466	            publish_url: None,
467	            confirm_timeout: None,
468	            publish_timeout: None,
469	        },
470	    );
471	
472	    if let Some(raw_regs) = raw.registries {
473	        for (k_str, reg) in raw_regs {
474	            let key = RegistryKey(k_str);
475	            let built_in_kind = match key.as_str() {
476	                RegistryKey::CRATES_IO => Some(Ecosystem::Cargo),
477	                RegistryKey::NPM => Some(Ecosystem::Npm),
478	                RegistryKey::PYPI => Some(Ecosystem::Pypi),
479	                _ => None,
480	            };
481	            let kind = match reg.kind.as_deref() {
482	                Some("cargo") => Ecosystem::Cargo,
483	                Some("npm") => Ecosystem::Npm,
484	                Some("pypi") => Ecosystem::Pypi,
485	                None => built_in_kind.ok_or_else(|| ConfigError::RegistryKindMissing {
486	                    registry: key.as_str().to_owned(),
487	                })?,
488	                Some(other) => {
489	                    return Err(ConfigError::UnknownKey {
490	                        path: callisto_toml.clone(),
491	                        key: format!("[registries] kind = {other:?}"),
492	                    })
493	                }
494	            };
495	            if reg.publish_url.is_some() && kind != Ecosystem::Pypi {
496	                return Err(ConfigError::UnknownKey {
497	                    path: callisto_toml.clone(),
498	                    key: format!(
499	                        "[registries.{}] publish-url (only a `pypi` registry has a separate upload route)",
500	                        key.as_str()
501	                    ),
502	                });
503	            }
504	            let registry_duration = |field: &str, value: Option<&str>| match value {
505	                None => Ok(None),
506	                Some(text) => super::duration::parse_duration(text)
507	                    .map(Some)
508	                    .ok_or_else(|| ConfigError::UnknownKey {
509	                        path: callisto_toml.clone(),
510	                        key: format!(
511	                            "[registries.{}] {field} = {text:?} (use a whole number with s, m or h, from 1s to 1h)",
512	                            key.as_str()
513	                        ),
514	                    }),
515	            };
516	            let confirm_timeout = registry_duration("confirm-timeout", reg.confirm_timeout.as_deref())?;
517	            let publish_timeout = registry_duration("publish-timeout", reg.publish_timeout.as_deref())?;
518	            registries.insert(
519	                key,
520	                RegistryConfig {
521	                    kind,
522	                    url: reg.url,
523	                    publish_url: reg.publish_url,
524	                    confirm_timeout,
525	                    publish_timeout,
526	                },
527	            );
528	        }
529	    }
530	
531	    let raw_groups = RawGroupTable {
532	        fixed: raw.fixed_group.unwrap_or_default(),
533	        linked: raw.linked_group.unwrap_or_default(),
534	    };
535	    GroupTable::validate_syntactic(&raw_groups)?;
536	
537	    if !raw_groups.fixed.is_empty() {
538	        provenance.insert(ConfigKey::FIXED_GROUP, ConfigProvenance::Explicit);
539	    }
540	    if !raw_groups.linked.is_empty() {
541	        provenance.insert(ConfigKey::LINKED_GROUP, ConfigProvenance::Explicit);
542	    }
543	
544	    // Resolve [[package]] blocks into per-package override rules.
545	    // Order is preserved: first matching rule wins during package construction.
546	    let mut packages: Vec<(PackageId, PackageConfig)> = Vec::new();
547	    for raw_pkg in raw.package.unwrap_or_default() {
548	        ConfigError::require_canonical_ecosystem(&raw_pkg.pattern, "[[package]] match")?;
549	        let pattern = PackageId::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
550	            path: callisto_toml.clone(),
551	            key: format!("[[package]] match = {:?}: {e}", raw_pkg.pattern),
552	        })?;
553	
554	        if raw_pkg.release_trigger.is_some() {
555	            provenance.insert(ConfigKey::RELEASE_TRIGGER, ConfigProvenance::Explicit);
556	        }
557	        if raw_pkg.tag_template.is_some() {
558	            provenance.insert(ConfigKey::TAG_TEMPLATE, ConfigProvenance::Explicit);
559	        }
560	        if raw_pkg.pre_major_inference.is_some() {
561	            provenance.insert(ConfigKey::PRE_MAJOR_INFERENCE, ConfigProvenance::Explicit);
562	        }
563	
564	        let cfg = parse_package_config_fields(
565	            &callisto_toml,
566	            "[[package]]",
567	            &raw_pkg.pattern,
568	            raw_pkg.release_trigger.as_deref(),
569	            raw_pkg.tag_template.as_deref(),
570	            raw_pkg.previous_tag_templates.as_deref(),
571	            raw_pkg.changelog.as_deref(),
572	            raw_pkg.pre_major_inference.as_deref(),
573	            raw_pkg.publish_to.as_deref(),
574	        )?;
575	
576	        packages.push((pattern, cfg));
577	    }
578	
579	    // Resolve [[package-set]] blocks into bulk config-override rules.
580	    // Semantics: each rule matches ALL packages whose PackageId matches the pattern.
581	    // A [[package]] rule takes priority; [[package-set]] is the fallback (see walk.rs).
582	    let mut package_sets: Vec<(PackagePattern, PackageConfig)> = Vec::new();
583	    for raw_pkg in raw.package_set.unwrap_or_default() {
584	        ConfigError::require_canonical_ecosystem(&raw_pkg.pattern, "[[package-set]] match")?;
585	        let pattern = PackagePattern::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
586	            path: callisto_toml.clone(),
587	            key: format!("[[package-set]] match = {:?}: {e}", raw_pkg.pattern),
588	        })?;
589	
590	        if raw_pkg.release_trigger.is_some() {
591	            provenance.insert(ConfigKey::RELEASE_TRIGGER, ConfigProvenance::Explicit);
592	        }
593	        if raw_pkg.tag_template.is_some() {
594	            provenance.insert(ConfigKey::TAG_TEMPLATE, ConfigProvenance::Explicit);
595	        }
596	        if raw_pkg.pre_major_inference.is_some() {
597	            provenance.insert(ConfigKey::PRE_MAJOR_INFERENCE, ConfigProvenance::Explicit);
598	        }
599	
600	        let cfg = parse_package_config_fields(
601	            &callisto_toml,
602	            "[[package-set]]",
603	            &raw_pkg.pattern,
604	            raw_pkg.release_trigger.as_deref(),
605	            raw_pkg.tag_template.as_deref(),
606	            None,
607	            raw_pkg.changelog.as_deref(),
608	            raw_pkg.pre_major_inference.as_deref(),
609	            raw_pkg.publish_to.as_deref(),
610	        )?;
611	
612	        package_sets.push((pattern, cfg));
613	    }
614	
615	    Ok(ResolvedConfig {
616	        root: root.to_path_buf(),
617	        changesets_dir,
618	        cascade: CascadeConfig {
619	            mode,
620	            bump_severity,
621	            peer_escalation,
622	            preserve_npm_ranges,
623	        },
624	        validation: ValidationConfig { allow_empty_changesets },
625	        product_release,
626	        registries,
627	        packages,
628	        package_sets,
629	        groups: GroupTable::default(),
630	        raw_groups,
631	        provenance,
632	    })
633	}
