/// Pre-1.0 (`0.y.z`) severity-downgrade policy. A closed 3-state choice --
/// modeled as an enum rather than two independent bools so the type system
/// rules out the unreachable-via-parser 4th combination a `{breaking_to_minor:
/// false, feat_to_patch: true}`-shaped struct literal could otherwise
/// construct.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum PreMajorInferencePolicy {
    #[default]
    Off,
    /// Downgrades an inferred Major bump to Minor.
    Conservative,
    /// Downgrades an inferred Major bump to Minor, and Minor to Patch.
    ConservativeFeat,
}

pub fn parse_publish_target(s: &str) -> Result<PublishTarget, ConfigError> {
    match s {
        "crates-io" => Ok(PublishTarget::CratesIo),
        "npm" => Ok(PublishTarget::Npm {
            registry: None,
            access: None,
        }),
        "pypi" => Ok(PublishTarget::Pypi { index: None }),
        "nuget" => Ok(PublishTarget::NuGet { source: None }),
        "github-release" => Ok(PublishTarget::GitHubRelease),
        "none" => Ok(PublishTarget::None),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("publish-to = {other:?}"),
        }),
    }
}

pub fn parse_release_trigger(s: &str) -> Result<ReleaseTrigger, ConfigError> {
    match s {
        "changeset" => Ok(ReleaseTrigger::Changeset),
        "auto" => Ok(ReleaseTrigger::Auto),
        other => Err(ConfigError::UnknownKey {
            path: PathBuf::new(),
            key: format!("release-trigger = {other}"),
        }),
    }
}

/// A `[[package]]` rule applies to a package when it has a manifest in the rule's ecosystem whose own name is the
/// rule's name.
///
/// `native_names` is the package's name in each ecosystem it has a manifest in. A dual package's names can differ per
/// ecosystem, so `npm/michi-node` does not apply to the package whose npm name is `@orin-dx/michi`, whatever its
/// directory or Cargo name is, which is the same identity a `[[fixed-group]]` member must give.
pub(crate) fn rule_applies(rule_id: &PackageId, native_names: &[(Ecosystem, &str)]) -> bool {
    rule_id.ecosystem().is_some_and(|eco| {
        native_names
            .iter()
            .any(|(ecosystem, name)| *ecosystem == eco && *name == rule_id.name())
    })
}

/// The first `[[package]]` rule, in TOML declaration order, that applies to `id`; `None` if none does.
///
/// MUST NOT sort or partition `cfg.packages`: declaration order is the specificity.
pub(crate) fn resolve_package_config<'a>(
    native_names: &[(Ecosystem, &str)],
    cfg: &'a ResolvedConfig,
) -> Option<&'a PackageConfig> {
    cfg.packages
        .iter()
        .find(|(rule_id, _)| rule_applies(rule_id, native_names))
        .map(|(_, pcfg)| pcfg)
}

pub fn parse_pre_major_policy(s: &str) -> Result<PreMajorInferencePolicy, ConfigError> {
    match s {
        "off" | "false" => Ok(PreMajorInferencePolicy::Off),
        "conservative" => Ok(PreMajorInferencePolicy::Conservative),
        "conservative-feat" => Ok(PreMajorInferencePolicy::ConservativeFeat),
        _ => Err(ConfigError::InvalidPreMajorInference { found: s.to_string() }),
    }
}

/// Parses the five override fields shared by `[[package]]` and
/// `[[package-set]]` blocks (release-trigger, tag-template, changelog,
/// pre-major-inference, publish-to) into a `PackageConfig`.
///
/// `previous_tag_templates` is `[[package]]`-only; `[[package-set]]` callers pass `None`.
#[allow(clippy::too_many_arguments)]
fn parse_package_config_fields(
    callisto_toml: &Path,
    error_prefix: &str,
    pattern_display: &str,
    release_trigger: Option<&str>,
    tag_template: Option<&str>,
    previous_tag_templates: Option<&[String]>,
    changelog: Option<&str>,
    pre_major_inference: Option<&str>,
    publish_to: Option<&[String]>,
) -> Result<PackageConfig, ConfigError> {
    let release_trigger = release_trigger.map(parse_release_trigger).transpose()?;

    let tag_template = tag_template
        .map(TagTemplate::parse)
        .transpose()
        .map_err(ConfigError::Tag)?;

    let previous_tag_templates = previous_tag_templates
        .unwrap_or_default()
        .iter()
        .map(|template| TagTemplate::parse(template))
        .collect::<Result<Vec<_>, _>>()
        .map_err(ConfigError::Tag)?;

    let changelog = changelog
        .map(|s| {
            callisto_model::workspace_relative(s).map_err(|_err| ConfigError::InvalidChangelogPath {
                pattern: pattern_display.to_string(),
                value: s.to_string(),
            })
        })
        .transpose()?;

    let pre_major_inference = pre_major_inference.map(parse_pre_major_policy).transpose()?;

    let publish_to = publish_to
        .map(|targets| {
            targets
                .iter()
                .map(|s| parse_publish_target(s))
                .collect::<Result<Vec<_>, _>>()
        })
        .transpose()
        .map_err(|e| match e {
            ConfigError::UnknownKey { key, .. } => ConfigError::UnknownKey {
                path: callisto_toml.to_path_buf(),
                key: format!("{error_prefix} publish-to: {key}"),
            },
            other => other,
        })?;

    Ok(PackageConfig {
        release_trigger,
        publish_to,
        tag_template,
        previous_tag_templates,
        changelog,
        pre_major_inference,
    })
}

/// Reads and parses `root/callisto.toml` (absent means empty), then [`resolve`]s it.
pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
    let callisto_toml = root.join("callisto.toml");
    let content = callisto_model::strict_fs::read_optional(&callisto_toml).map_err(|e| ConfigError::Read {
        path: callisto_toml.clone(),
        message: e.to_string(),
    })?;
    let raw = if let Some(content) = content {
        toml::from_str::<RawConfig>(&content).map_err(|e| ConfigError::ParseToml {
            path: callisto_toml.clone(),
            message: e.to_string(),
        })?
    } else {
        RawConfig::default()
    };
    resolve(root, raw)
}

/// Validates and defaults an already-parsed config for the workspace at `root`.
pub fn resolve(root: &Path, raw: RawConfig) -> Result<ResolvedConfig, ConfigError> {
    let callisto_toml = root.join("callisto.toml");
    let mut provenance = BTreeMap::new();
    let product_release = raw.release.map(resolve_product_release).transpose()?;

    let changesets_dir_str = raw
        .changesets
        .as_ref()
        .and_then(|c| c.dir.as_deref())
        .unwrap_or(".changeset");

    // Reject any changesets.dir value that is absolute or contains '..'
    // components — either would allow load_changesets / atomic_write to
    // escape the workspace root. We check components() rather than
    // canonicalizing because the directory may not exist yet (e.g. a fresh
    // workspace).
    let changesets_dir =
        callisto_model::workspace_relative(changesets_dir_str).map_err(|_err| ConfigError::InvalidChangesetsDir {
            dir: changesets_dir_str.to_string(),
        })?;

    let cascade_raw = raw.cascade.unwrap_or_default();
    let mode = match cascade_raw.mode.as_deref() {
        Some("always") => {
            provenance.insert(ConfigKey::CASCADE_MODE, ConfigProvenance::Explicit);
            CascadeMode::Always
        }
        Some("out-of-range") | None => CascadeMode::OutOfRange,
        Some(other) => {
            return Err(ConfigError::UnknownKey {
                path: callisto_toml,
                key: format!("cascade.mode = {other}"),
            })
        }
    };

    let bump_severity = match cascade_raw.bump_severity.as_deref() {
        Some("minor") => {
            provenance.insert(ConfigKey::CASCADE_BUMP_SEVERITY, ConfigProvenance::Explicit);
            CascadeBumpSeverity::Minor
        }
        Some("patch") | None => CascadeBumpSeverity::Patch,
        Some(other) => {
            return Err(ConfigError::InvalidBumpSeverity {
                found: other.to_string(),
            })
        }
    };

    let peer_escalation = cascade_raw.peer_escalation.unwrap_or(true);
    if cascade_raw.peer_escalation.is_some() {
        provenance.insert(ConfigKey::CASCADE_PEER_ESCALATION, ConfigProvenance::Explicit);
    }

    let preserve_npm_ranges = cascade_raw.preserve_npm_ranges.unwrap_or(true);
    if cascade_raw.preserve_npm_ranges.is_some() {
        provenance.insert(ConfigKey::CASCADE_PRESERVE_NPM_RANGES, ConfigProvenance::Explicit);
    }

    let validation_raw = raw.validation.unwrap_or_default();
    let allow_empty_changesets = validation_raw.allow_empty_changesets.unwrap_or(false);
    if validation_raw.allow_empty_changesets.is_some() {
        provenance.insert(ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS, ConfigProvenance::Explicit);
    }

    let mut registries = BTreeMap::new();
    registries.insert(
        RegistryKey(RegistryKey::CRATES_IO.to_string()),
        RegistryConfig {
            kind: Ecosystem::Cargo,
            url: None,
            publish_url: None,
            confirm_timeout: None,
            publish_timeout: None,
        },
    );
    registries.insert(
        RegistryKey(RegistryKey::NPM.to_string()),
        RegistryConfig {
            kind: Ecosystem::Npm,
            url: None,
            publish_url: None,
            confirm_timeout: None,
            publish_timeout: None,
        },
    );

    if let Some(raw_regs) = raw.registries {
        for (k_str, reg) in raw_regs {
            let key = RegistryKey(k_str);
            let built_in_kind = match key.as_str() {
                RegistryKey::CRATES_IO => Some(Ecosystem::Cargo),
                RegistryKey::NPM => Some(Ecosystem::Npm),
                RegistryKey::PYPI => Some(Ecosystem::Pypi),
                _ => None,
            };
            let kind = match reg.kind.as_deref() {
                Some("cargo") => Ecosystem::Cargo,
                Some("npm") => Ecosystem::Npm,
                Some("pypi") => Ecosystem::Pypi,
                None => built_in_kind.ok_or_else(|| ConfigError::RegistryKindMissing {
                    registry: key.as_str().to_owned(),
                })?,
                Some(other) => {
                    return Err(ConfigError::UnknownKey {
                        path: callisto_toml.clone(),
                        key: format!("[registries] kind = {other:?}"),
                    })
                }
            };
            if reg.publish_url.is_some() && kind != Ecosystem::Pypi {
                return Err(ConfigError::UnknownKey {
                    path: callisto_toml.clone(),
                    key: format!(
                        "[registries.{}] publish-url (only a `pypi` registry has a separate upload route)",
                        key.as_str()
                    ),
                });
            }
            let registry_duration = |field: &str, value: Option<&str>| match value {
                None => Ok(None),
                Some(text) => super::duration::parse_duration(text)
                    .map(Some)
                    .ok_or_else(|| ConfigError::UnknownKey {
                        path: callisto_toml.clone(),
                        key: format!(
                            "[registries.{}] {field} = {text:?} (use a whole number with s, m or h, from 1s to 1h)",
                            key.as_str()
                        ),
                    }),
            };
            let confirm_timeout = registry_duration("confirm-timeout", reg.confirm_timeout.as_deref())?;
            let publish_timeout = registry_duration("publish-timeout", reg.publish_timeout.as_deref())?;
            registries.insert(
                key,
                RegistryConfig {
                    kind,
                    url: reg.url,
                    publish_url: reg.publish_url,
                    confirm_timeout,
                    publish_timeout,
                },
            );
        }
    }

    let raw_groups = RawGroupTable {
        fixed: raw.fixed_group.unwrap_or_default(),
        linked: raw.linked_group.unwrap_or_default(),
    };
    GroupTable::validate_syntactic(&raw_groups)?;

    if !raw_groups.fixed.is_empty() {
        provenance.insert(ConfigKey::FIXED_GROUP, ConfigProvenance::Explicit);
    }
    if !raw_groups.linked.is_empty() {
        provenance.insert(ConfigKey::LINKED_GROUP, ConfigProvenance::Explicit);
    }

    // Resolve [[package]] blocks into per-package override rules.
    // Order is preserved: first matching rule wins during package construction.
    let mut packages: Vec<(PackageId, PackageConfig)> = Vec::new();
    for raw_pkg in raw.package.unwrap_or_default() {
        ConfigError::require_canonical_ecosystem(&raw_pkg.pattern, "[[package]] match")?;
        let pattern = PackageId::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
            path: callisto_toml.clone(),
            key: format!("[[package]] match = {:?}: {e}", raw_pkg.pattern),
        })?;

        if raw_pkg.release_trigger.is_some() {
            provenance.insert(ConfigKey::RELEASE_TRIGGER, ConfigProvenance::Explicit);
        }
        if raw_pkg.tag_template.is_some() {
            provenance.insert(ConfigKey::TAG_TEMPLATE, ConfigProvenance::Explicit);
        }
        if raw_pkg.pre_major_inference.is_some() {
            provenance.insert(ConfigKey::PRE_MAJOR_INFERENCE, ConfigProvenance::Explicit);
        }

        let cfg = parse_package_config_fields(
            &callisto_toml,
            "[[package]]",
            &raw_pkg.pattern,
            raw_pkg.release_trigger.as_deref(),
            raw_pkg.tag_template.as_deref(),
            raw_pkg.previous_tag_templates.as_deref(),
            raw_pkg.changelog.as_deref(),
            raw_pkg.pre_major_inference.as_deref(),
            raw_pkg.publish_to.as_deref(),
        )?;

        packages.push((pattern, cfg));
    }

    // Resolve [[package-set]] blocks into bulk config-override rules.
    // Semantics: each rule matches ALL packages whose PackageId matches the pattern.
    // A [[package]] rule takes priority; [[package-set]] is the fallback (see walk.rs).
    let mut package_sets: Vec<(PackagePattern, PackageConfig)> = Vec::new();
    for raw_pkg in raw.package_set.unwrap_or_default() {
        ConfigError::require_canonical_ecosystem(&raw_pkg.pattern, "[[package-set]] match")?;
        let pattern = PackagePattern::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
            path: callisto_toml.clone(),
            key: format!("[[package-set]] match = {:?}: {e}", raw_pkg.pattern),
        })?;

        if raw_pkg.release_trigger.is_some() {
            provenance.insert(ConfigKey::RELEASE_TRIGGER, ConfigProvenance::Explicit);
        }
        if raw_pkg.tag_template.is_some() {
            provenance.insert(ConfigKey::TAG_TEMPLATE, ConfigProvenance::Explicit);
        }
        if raw_pkg.pre_major_inference.is_some() {
            provenance.insert(ConfigKey::PRE_MAJOR_INFERENCE, ConfigProvenance::Explicit);
        }

        let cfg = parse_package_config_fields(
            &callisto_toml,
            "[[package-set]]",
            &raw_pkg.pattern,
            raw_pkg.release_trigger.as_deref(),
            raw_pkg.tag_template.as_deref(),
            None,
            raw_pkg.changelog.as_deref(),
            raw_pkg.pre_major_inference.as_deref(),
            raw_pkg.publish_to.as_deref(),
        )?;

        package_sets.push((pattern, cfg));
    }

    Ok(ResolvedConfig {
        root: root.to_path_buf(),
        changesets_dir,
        cascade: CascadeConfig {
            mode,
            bump_severity,
            peer_escalation,
            preserve_npm_ranges,
        },
        validation: ValidationConfig { allow_empty_changesets },
        product_release,
        registries,
        packages,
        package_sets,
        groups: GroupTable::default(),
        raw_groups,
        provenance,
    })
}

