        let ws = tmp.path().join("ws");
        fs::create_dir(&ws).unwrap();
        fs::write(ws.join("callisto.toml"), "").unwrap();
        let Some(_locked) = callisto_fixtures::locked_dir::LockedDir::lock(&ws) else {
            return;
