95	    /// dependency edges resolved. Every command that plans or applies a release loads through here.
96	    ///
97	    /// # Errors
98	    ///
99	    /// Discovery or config loading fails, or a discovered manifest could not be resolved
100	    /// ([`GraphError::IncompleteWorkspace`]).
101	    pub fn load<L: ProjectLocator>(root: PathBuf, locator: &L, runner: &'a R) -> Result<Self, GraphError> {
102	        let config = config::load(&root)?;
103	        Self::load_with_config(root, config, locator, runner)
104	    }
105	
106	    /// Like [`Workspace::load`] against an already-resolved config instead of `callisto.toml`.
107	    pub fn load_with_config<L: ProjectLocator>(
108	        root: PathBuf,
109	        config: ResolvedConfig,
110	        locator: &L,
111	        runner: &'a R,
112	    ) -> Result<Self, GraphError> {
113	        let workspace = Self::assemble(root, config, locator, runner)?;
114	        workspace.require_complete()?;
115	        Ok(workspace)
116	    }
117	
118	    fn assemble<L: ProjectLocator>(
119	        root: PathBuf,
120	        mut config: ResolvedConfig,
121	        locator: &L,
122	        runner: &'a R,
123	    ) -> Result<Self, GraphError> {
124	        let manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>> = RefCell::new(BTreeMap::new());
125	        let graph = ManifestWalkResolver::build(&root, locator, runner, &config, &manifest_cache)?;
126	
127	        config.groups = GroupTable::resolve(&config.raw_groups, graph.identity())?;
128	
129	        let identity = graph.identity().clone();
130	
131	        Ok(Workspace {
132	            root,
133	            config,
134	            graph,
135	            tags: OnceCell::new(),
136	            git: OnceCell::new(),
137	            runner,
138	            manifest_cache,
139	            identity,
140	        })
141	    }
142	}
143	
144	impl<'a, R: CommandRunner, D: DependencyResolver> Workspace<'a, R, D> {
145	    /// Fails if the walk dropped a manifest it could not resolve, because a release planned from the rest would be
146	    /// smaller than the repository.
147	    ///
148	    /// # Errors
149	    ///
150	    /// [`GraphError::IncompleteWorkspace`] naming every unresolved manifest.
151	    pub fn require_complete(&self) -> Result<(), GraphError> {
152	        // One manifest can fail in several stages of the walk; name it once.
153	        let mut seen = BTreeSet::new();
154	        let unresolved: Vec<String> = self
155	            .graph
156	            .diagnostics()
157	            .iter()
158	            .filter(|diagnostic| diagnostic.code == callisto_model::DiagnosticCode::ManifestUnresolved)
159	            .filter(|diagnostic| diagnostic.path.as_ref().is_none_or(|path| seen.insert(path.clone())))
160	            .map(|diagnostic| diagnostic.message.clone())
161	            .collect();
162	        if unresolved.is_empty() {
163	            Ok(())
164	        } else {
165	            Err(GraphError::IncompleteWorkspace { unresolved })
166	        }
167	    }
168	
169	    /// Each package's id as reports print it.
170	    pub fn report_ids(&self) -> plan::ReportIds {
171	        plan::ReportIds::new(self.graph.packages())
172	    }
173	
174	    /// Returns the workspace's [`TagIndex`], building it on first access and
175	    /// reusing the cached result afterwards. See the doc comment on the
176	    /// `tags` field for why this is deferred rather than built eagerly by
177	    /// [`Workspace::load`].
178	    pub fn tags(&self) -> Result<&TagIndex, GraphError> {
179	        if let Some(existing) = self.tags.get() {
180	            return Ok(existing);
181	        }
182	        let built = TagIndex::build(self.git_access(), &self.graph, &self.identity, &self.config)?;
183	        // `OnceCell::set` only fails if another write already raced it in;
184	        // `Workspace` is only ever accessed through `&self` here (never
185	        // shared across threads -- `R`/`D` carry no such bound), so the
186	        // `get()` check above already ruled that out. Fall back to `get()`
187	        // either way rather than trusting the `set` call's own return value,
188	        // so this stays correct even if that assumption ever changes.
189	        self.tags.set(built).ok();
190	        Ok(self
191	            .tags
192	            .get()
193	            .expect("tags was just set above, or already set by a prior call"))
194	    }
195	
196	    /// Returns the workspace's shared [`GitAccess`], rooted at the workspace
197	    /// root and running `git` through the workspace's runner.
198	    pub fn git_access(&self) -> &GitAccess<'a> {
199	        self.git.get_or_init(|| GitAccess::new(&self.root, self.runner))
200	    }
201	
202	    pub fn base_versions(&self) -> Result<BTreeMap<PackageId, Version>, GraphError> {
203	        let ctx = callisto_manifests::OpenContext::for_workspace_root(&self.root)?;
204	
205	        let mut versions = BTreeMap::new();
206	        for pkg in self.graph.packages() {
207	            let mut found_version = None;
208	            for decl in &pkg.manifests {
209	                if decl.role == callisto_model::ManifestRole::Canonical {
210	                    let handle = manifest_cache::open_cached(&self.manifest_cache, decl, &ctx)?;
211	                    let v = handle.current_version()?;
212	                    found_version = Some(v);
213	                    break;
214	                }
215	            }
216	            if let Some(version) = found_version {
217	                versions.insert(pkg.id.clone(), version);
218	            } else {
219	                return Err(GraphError::Manifest(callisto_model::ManifestError::MissingField {
220	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
221	                    field: "version",
222	                }));
223	            }
224	        }
225	        Ok(versions)
226	    }
227	
228	    pub fn initial_versions(&self) -> Result<Vec<(String, Version)>, GraphError> {
229	        let base = self.base_versions()?;
230	        Ok(base.into_iter().map(|(id, v)| (pre_json_key(&id), v)).collect())
231	    }
232	
233	    /// Resolves stored baselines to their owners before applying the owners' native version grammars.
234	    pub fn resolve_pre_state(
235	        &self,
236	        state: callisto_model::format::PreState,
237	    ) -> Result<callisto_model::format::PreState, GraphError> {
238	        let raw_versions = state
239	            .initial_versions
240	            .iter()
241	            .map(|(key, version)| (key.clone(), version.raw().to_string()))
242	            .collect();
243	        self.resolve_pre_state_with_raw_versions(state, &raw_versions)
244	    }
245	
246	    /// Resolves stored baselines using their original JSON spellings.
247	    pub fn resolve_pre_state_from_json(
248	        &self,
249	        state: callisto_model::format::PreState,
250	        original_json: &str,
251	    ) -> Result<callisto_model::format::PreState, GraphError> {
252	        let clean_json = original_json.strip_prefix('\u{FEFF}').unwrap_or(original_json);
253	        let value: serde_json::Value = serde_json::from_str(clean_json).map_err(|error| {
254	            GraphError::PreJson(callisto_model::format::PreJsonError::Malformed {
255	                message: error.to_string(),
256	            })
257	        })?;
258	        let raw_versions: indexmap::IndexMap<String, String> = value
259	            .get("initialVersions")
260	            .and_then(serde_json::Value::as_object)
261	            .into_iter()
262	            .flat_map(|values| values.iter())
263	            .filter_map(|(key, value)| value.as_str().map(|raw| (key.clone(), raw.to_string())))
264	            .collect();
265	        self.resolve_pre_state_with_raw_versions(state, &raw_versions)
266	    }
267	
268	    fn resolve_pre_state_with_raw_versions(
269	        &self,
270	        state: callisto_model::format::PreState,
271	        raw_versions: &indexmap::IndexMap<String, String>,
272	    ) -> Result<callisto_model::format::PreState, GraphError> {
273	        assign_promoted_pre_keys(
274	            self.git_access(),
275	            &self.graph,
276	            &self.identity,
277	            &self.config.pre_json_path(),
278	            state,
279	            raw_versions,
280	        )
281	    }
282	}
283	
284	/// The `pre.json` `initialVersions` key for `id`: its display id, so `cargo/foo` and `npm/foo` never share an entry.
285	pub fn pre_json_key(id: &PackageId) -> String {
286	    id.display_name()
287	}
288	
289	/// `id`'s pinned pre-release baseline.
290	pub fn pre_initial_version<'a>(pre: &'a callisto_model::format::PreState, id: &PackageId) -> Option<&'a Version> {
291	    pre.initial_versions.get(&pre_json_key(id))
292	}
293	
294	/// The commit that added `pre_json`, asked of Git once however many keys need it.
295	fn commit_added<'c>(
296	    cache: &'c mut Option<Option<String>>,
297	    git: &GitAccess<'_>,
298	    pre_json: &std::path::Path,
299	) -> Result<Option<&'c str>, GraphError> {
300	    if cache.is_none() {
301	        *cache = Some(git.commit_adding(pre_json).map_err(GraphError::Vcs)?);
302	    }
303	    Ok(cache.as_ref().and_then(Option::as_deref))
304	}
305	
306	/// Whether `package`, which carries the bare `key` today, may be the package that held it when `pre.json` was added.
307	///
308	/// History that cannot be read is no evidence of another owner, so it keeps the key.
309	fn bare_key_may_belong(
310	    git: &GitAccess<'_>,
311	    added: &mut Option<Option<String>>,
312	    pre_json: &std::path::Path,
313	    key: &str,
314	    package: &callisto_model::Package,
315	    identity: &IdentityIndex,
316	    rosters: &mut history::Rosters,
317	) -> bool {
318	    let held = commit_added(added, git, pre_json).and_then(|rev| match rev {
319	        Some(rev) => history::may_have_held_name_at(git, rev, key, package, identity, rosters),
320	        None => Ok(true),
321	    });
322	    held.unwrap_or(true)
323	}
324	
325	/// Resolves native baselines, attributing historical bare keys at the commit that added `pre.json`.
326	pub(crate) fn assign_promoted_pre_keys<D: DependencyResolver>(
327	    git: &GitAccess<'_>,
328	    graph: &D,
329	    identity: &IdentityIndex,
330	    pre_json: &std::path::Path,
331	    mut state: callisto_model::format::PreState,
332	    raw_versions: &indexmap::IndexMap<String, String>,
333	) -> Result<callisto_model::format::PreState, GraphError> {
334	    let keys: Vec<String> = state.initial_versions.keys().cloned().collect();
335	    let mut owners = BTreeMap::new();
336	    let mut rosters = history::Rosters::default();
337	    let mut added = None;
338	    for key in &keys {
339	        if let Some(owner) = graph.packages().find(|p| pre_json_key(&p.id) == *key) {
340	            if owner.id.ecosystem().is_some()
341	                || bare_key_may_belong(git, &mut added, pre_json, key, owner, identity, &mut rosters)
342	            {
343	                owners.insert(key.clone(), owner);
344	            } else {
345	                // Another package's baseline: it must not pin this package's version either.
346	                state.initial_versions.shift_remove(key);
347	            }
348	            continue;
349	        }
350	        let same: Vec<&callisto_model::Package> = graph
351	            .packages()
352	            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
353	            .collect();
354	        let owner = if same.is_empty() {
355	            match identity.resolve(key) {
356	                Ok(id) => {
357	                    let package = graph.packages().find(|p| p.id == id);
358	                    package.filter(|package| {
359	                        PackageId::parse(key).is_ok_and(|parsed| parsed.ecosystem().is_some())
360	                            || bare_key_may_belong(git, &mut added, pre_json, key, package, identity, &mut rosters)
361	                    })
362	                }
363	                Err(GraphError::UnknownPackage { .. }) => None,
364	                Err(GraphError::AmbiguousName { candidates, .. }) => {
365	                    return Err(GraphError::AmbiguousPreJsonKey {
366	                        key: key.clone(),
367	                        candidates,
368	                    });
369	                }
370	                Err(error) => return Err(error),
371	            }
372	        } else {
373	            let owner = match commit_added(&mut added, git, pre_json)? {
374	                Some(rev) => history::sole_owner_at(git, rev, key, &same, identity, &mut rosters)?,
375	                None => None,
376	            };
377	            Some(owner.ok_or_else(|| GraphError::AmbiguousPreJsonKey {
378	                key: key.clone(),
379	                candidates: same.iter().map(|p| p.id.clone()).collect(),
380	            })?)
381	        };
382	        if let Some(owner) = owner {
383	            owners.insert(key.clone(), owner);
384	        }
385	    }
386	    state
387	        .resolve_initial_versions_from_raw(raw_versions, |key| {
388	            owners
389	                .get(key)
390	                .and_then(|owner| owner.canonical_manifests().next().map(|manifest| manifest.ecosystem()))
391	        })
392	        .map_err(GraphError::PreJson)?;
393	    let mut legacy_by_owner_key: BTreeMap<String, Vec<String>> = BTreeMap::new();
394	    for key in keys {
395	        if let Some(owner) = owners.get(&key) {
396	            let owner_key = pre_json_key(&owner.id);
397	            if owner_key != key {
398	                legacy_by_owner_key.entry(owner_key).or_default().push(key);
399	            }
400	        }
401	    }
402	    // Every key for one package must agree before anything moves.
403	    for (owner_key, legacy_keys) in &legacy_by_owner_key {
404	        let reference = if state.initial_versions.contains_key(owner_key) {
405	            owner_key
406	        } else {
407	            &legacy_keys[0]
408	        };
409	        let reference_version = &state.initial_versions[reference];
410	        for key in legacy_keys.iter().filter(|key| *key != reference) {
411	            let version = &state.initial_versions[key];
412	            if version.compare(reference_version) != Ok(std::cmp::Ordering::Equal) {
413	                return Err(GraphError::ConflictingPreJsonBaselines {
414	                    key: key.clone(),
415	                    version: version.clone(),
416	                    other_key: reference.clone(),
417	                    other_version: reference_version.clone(),
418	                });
419	            }
420	        }
421	    }
422	    for (owner_key, legacy_keys) in legacy_by_owner_key {
423	        for key in legacy_keys {
424	            if let Some(version) = state.initial_versions.shift_remove(&key) {
425	                state.initial_versions.entry(owner_key.clone()).or_insert(version);
426	            }
427	        }
428	    }
429	    Ok(state)
430	}
431	
432	#[cfg(test)]
433	mod pre_json_key_tests {
434	    use super::*;
435	    use callisto_model::format::PreState;
436	    use callisto_model::Ecosystem;
437	
438	    fn prefixed(ecosystem: Ecosystem, name: &str) -> PackageId {
439	        PackageId::Prefixed {
440	            ecosystem,
441	            name: name.to_string(),
442	        }
443	    }
444	
445	    #[test]
446	    fn same_named_packages_in_two_ecosystems_keep_separate_baselines() {
447	        let cargo = prefixed(Ecosystem::Cargo, "foo");
448	        let npm = prefixed(Ecosystem::Npm, "foo");
449	        let pre = PreState::entering(
450	            "beta",
451	            [
452	                (pre_json_key(&cargo), Version::semver(1, 0, 0)),
453	                (pre_json_key(&npm), Version::semver(2, 0, 0)),
454	            ],
455	        );
456	        assert_eq!(pre_initial_version(&pre, &cargo), Some(&Version::semver(1, 0, 0)));
457	        assert_eq!(pre_initial_version(&pre, &npm), Some(&Version::semver(2, 0, 0)));
458	    }
459	}
