350	        let same: Vec<&callisto_model::Package> = graph
351	            .packages()
352	            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
353	            .collect();
354	        let owner = if same.is_empty() {
355	            match identity.resolve(key) {
356	                Ok(id) => {
357	                    let package = graph.packages().find(|p| p.id == id);
358	                    package.filter(|package| {
359	                        PackageId::parse(key).is_ok_and(|parsed| parsed.ecosystem().is_some())
360	                            || bare_key_may_belong(git, &mut added, pre_json, key, package, identity, &mut rosters)
361	                    })
362	                }
363	                Err(GraphError::UnknownPackage { .. }) => None,
364	                Err(GraphError::AmbiguousName { candidates, .. }) => {
365	                    return Err(GraphError::AmbiguousPreJsonKey {
366	                        key: key.clone(),
367	                        candidates,
368	                    });
369	                }
370	                Err(error) => return Err(error),
371	            }
372	        } else {
373	            let owner = match commit_added(&mut added, git, pre_json)? {
374	                Some(rev) => history::sole_owner_at(git, rev, key, &same, identity, &mut rosters)?,
375	                None => None,
376	            };
377	            Some(owner.ok_or_else(|| GraphError::AmbiguousPreJsonKey {
378	                key: key.clone(),
379	                candidates: same.iter().map(|p| p.id.clone()).collect(),
380	            })?)
381	        };
382	        if let Some(owner) = owner {
383	            owners.insert(key.clone(), owner);
384	        }
385	    }
386	    state
387	        .resolve_initial_versions_from_raw(raw_versions, |key| {
388	            owners
389	                .get(key)
390	                .and_then(|owner| owner.canonical_manifests().next().map(|manifest| manifest.ecosystem()))
391	        })
392	        .map_err(GraphError::PreJson)?;
393	    let mut legacy_by_owner_key: BTreeMap<String, Vec<String>> = BTreeMap::new();
394	    for key in keys {
395	        if let Some(owner) = owners.get(&key) {
396	            let owner_key = pre_json_key(&owner.id);
397	            if owner_key != key {
398	                legacy_by_owner_key.entry(owner_key).or_default().push(key);
399	            }
400	        }
401	    }
402	    // Every key for one package must agree before anything moves.
403	    for (owner_key, legacy_keys) in &legacy_by_owner_key {
404	        let reference = if state.initial_versions.contains_key(owner_key) {
405	            owner_key
406	        } else {
407	            &legacy_keys[0]
408	        };
409	        let reference_version = &state.initial_versions[reference];
410	        for key in legacy_keys.iter().filter(|key| *key != reference) {
411	            let version = &state.initial_versions[key];
412	            if version.compare(reference_version) != Ok(std::cmp::Ordering::Equal) {
413	                return Err(GraphError::ConflictingPreJsonBaselines {
414	                    key: key.clone(),
415	                    version: version.clone(),
416	                    other_key: reference.clone(),
417	                    other_version: reference_version.clone(),
418	                });
419	            }
420	        }
421	    }
422	    for (owner_key, legacy_keys) in legacy_by_owner_key {
423	        for key in legacy_keys {
424	            if let Some(version) = state.initial_versions.shift_remove(&key) {
425	                state.initial_versions.entry(owner_key.clone()).or_insert(version);
426	            }
427	        }
428	    }
429	    Ok(state)
430	}
